91: async function loadFullPack(pins) {
92:     fs.mkdirSync(cacheDir, { recursive: true });
93:     const cacheFile = path.join(cacheDir, `${pins.pack}-${pins.locCommit}.json`);
94:     if (!fs.existsSync(cacheFile)) {
95:         const url = `https://raw.githubusercontent.com/microsoft/vscode-loc/${pins.locCommit}/i18n/${pins.pack}/translations/main.i18n.json`;
96:         const response = await fetchWithRetry(url);
97:         fs.writeFileSync(cacheFile, await response.text());
98:     }
99:     const contents = JSON.parse(fs.readFileSync(cacheFile, 'utf8')).contents;
100:     if (!contents || typeof contents !== 'object')
101:         throw new Error(`invalid language pack: ${cacheFile}`);
102:     return contents;
103: }
