109: async function extractLangpacks() {
110:     const locales = selectedLangpacks();
111:     if (!locales.length) return;
112:     const index = readJson(path.join(dataDir, 'vscode.index.json'));
113:     for (const locale of locales) {
114:         const file = path.join(dataDir, `vscode.langpack.${locale}.json`);
115:         const current = readJson(file);
116:         const pins = current.vscode;
117:         if (!pins?.pack || !pins?.locCommit) {
118:             fail(`VS Code ${locale}: missing vscode.pack or vscode.locCommit in ${path.basename(file)}`);
119:             continue;
120:         }
121:         let full;
122:         try {
123:             full = await loadFullPack(pins);
124:         } catch (error) {
125:             fail(`VS Code ${locale}: ${error.message}`);
126:             continue;
127:         }
128:         const contents = {};
129:         const errors = [];
130:         for (const [english, entries] of Object.entries(index.keys ?? {})) {
131:             for (const { source, module, key } of entries) {
132:                 const value = full[module]?.[key];
133:                 if (typeof value !== 'string' || !value) {
134:                     errors.push(`"${english}": ${module}::${key} is missing from ${pins.pack}`);
135:                     continue;
136:                 }
137:                 (contents[source] ??= {});
138:                 (contents[source][module] ??= {});
139:                 contents[source][module][key] = value;
140:             }
141:         }
142:         if (errors.length) {
143:             console.error(`VS Code ${locale}:`);
144:             for (const error of errors) console.error(`- ${error}`);
145:             failed = true;
146:             continue;
147:         }
148:         const ordered = {};
149:         for (const source of Object.keys(current.contents ?? {})) {
150:             for (const module of Object.keys(current.contents[source])) {
151:                 for (const key of Object.keys(current.contents[source][module])) {
152:                     const value = contents[source]?.[module]?.[key];
153:                     if (value === undefined) continue;
154:                     (ordered[source] ??= {});
155:                     (ordered[source][module] ??= {});
156:                     ordered[source][module][key] = value;
157:                 }
158:             }
159:         }
160:         for (const source of Object.keys(contents).sort()) {
161:             for (const module of Object.keys(contents[source]).sort()) {
162:                 for (const key of Object.keys(contents[source][module]).sort()) {
163:                     if (ordered[source]?.[module]?.[key] !== undefined) continue;
164:                     (ordered[source] ??= {});
165:                     (ordered[source][module] ??= {});
166:                     ordered[source][module][key] = contents[source][module][key];
167:                 }
168:             }
169:         }
170:         const entries = Object.values(ordered).reduce(
171:             (sum, modules) => sum + Object.values(modules).reduce((count, keys) => count + Object.keys(keys).length, 0),
172:             0,
173:         );
174:         const output = JSON.stringify({ vscode: pins, contents: ordered }, null, 2) + '\n';
175:         if (check) {
176:             const committed = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
177:             if (committed !== output) {
178:                 fail(`VS Code ${locale}: language-pack subset is out of date; run:\n  node scripts/i18n/i18n.mjs --locale=${locale}`);
179:             } else {
180:                 console.log(`VS Code ${locale}: ${entries} entries for ${Object.keys(index.keys ?? {}).length} English keys, up to date.`);
181:             }
182:         } else {
183:             fs.writeFileSync(file, output);
184:             console.log(`VS Code ${locale}: extracted ${entries} entries for ${Object.keys(index.keys ?? {}).length} English keys.`);
185:         }
186:     }
187: }
