338: function walk(directory, output = []) {
339:     for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
340:         const full = path.join(directory, entry.name);
341:         if (entry.isDirectory()) walk(full, output);
342:         else output.push(full);
343:     }
344:     return output;
345: }
