355: function scanMonacoCalls(esmRoot) {
356:     const calls = [];
357:     const files = walk(esmRoot).filter(file => file.endsWith('.js'));
358:     const pattern = /\blocalize2?\s*\(\s*(?:'((?:[^'\\]|\\.)*)'|"((?:[^"\\]|\\.)*)")\s*,\s*(?:'((?:[^'\\]|\\.)*)'|"((?:[^"\\]|\\.)*)")/g;
359:     for (const file of files) {
360:         const source = fs.readFileSync(file, 'utf8');
361:         const module = path.relative(esmRoot, file).replace(/\\/g, '/').replace(/\.js$/, '');
362:         let match;
363:         while ((match = pattern.exec(source))) {
364:             calls.push({
365:                 module,
366:                 key: decodeString(match[1] ?? match[2]),
367:                 english: decodeString(match[3] ?? match[4]),
368:             });
369:         }
370:     }
371:     return calls;
372: }
