476: function checkProvenance() {
477:     const errors = [];
478:     const readJsonSafe = file => {
479:         try {
480:             return JSON.parse(fs.readFileSync(file, 'utf8'));
481:         } catch (error) {
482:             errors.push(`${path.relative(frontendRoot, file)}: ${error.message}`);
483:             return {};
484:         }
485:     };
486:     const parseKeys = file => {
487:         const keys = new Set();
488:         const source = fs.readFileSync(path.join(messagesDir, file), 'utf8');
489:         for (const match of source.matchAll(/^\s*"((?:[^"\\]|\\.)*)"\s*:/gm))
490:             keys.add(JSON.parse('"' + match[1] + '"'));
491:         return keys;
492:     };
493: 
494:     const sources = readJsonSafe(path.join(messagesDir, 'sources.json'));
495:     if (sources.vscode?.tag !== VSCODE_LOC_TAG || sources.vscode?.commit !== VSCODE_LOC_COMMIT)
496:         errors.push('sources.json: vscode tag/commit do not match the pinned release');
497:     if (sources.vscode?.source !== 'microsoft/vscode-loc')
498:         errors.push('sources.json: expected source microsoft/vscode-loc');
499:     if (sources.vscode?.license !== 'MIT')
500:         errors.push('sources.json: expected MIT license');
