518:         const originCounts = new Map();
519:         const vscodeSourceCounts = new Map();
520:         let overrides = 0;
521:         let vscodeMatches = 0;
522:         for (const key of keys) {
523:             const entry = catalog.manifest.keys?.[key];
524:             if (!entry) {
525:                 errors.push(`${catalog.file}: key "${key}" has no explicit provenance`);
526:                 continue;
527:             }
